{"tool":"write","arguments":"{\"content\":\"\\\"\\\"\\\"按截图口径复现：离线 DQN（先收集经验再用经验回放训练），1 周 = 1 个 episode。\\n\\n这一版严格按截图描述：\\n  * 状态：负荷 / 光伏 / 风电 / SOC / 电价 五维\\n  * 网络：三层全连接（64-64-32），输出 充电/放电/买电/卖电 四动作 Q 值\\n  * 训练：经验回放（固定回放池离线训练）+ 目标网络\\n  * 每个 episode 是连续 1 章的\\\"典型周\\\"；评估在独立种子的新周上进行\\n\\n  python run_experiment.py --mode offline --episodes 400 --warmup-eps 20\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport dataclasses\\nimport os\\nimport time\\n\\nimport numpy as np\\n\\nimport dqn_agent as da\\nfrom grid_env import EnvConfig, GridDispatchEnv\\n\\n\\ndef train_offline(cfg_factory, warmup_eps=20, total_eps=400, updates_per_ep=300, batch_size=64,\\n                  lr=3e-4, gamma=0.99, eps_start=1.0, eps_end=0.05, tau=0.005, seed=0,\\n                  hidden=(64, 64, 32), verbose=True, log_every=20):\\n    \\\"\\\"\\\"采集 + 离线回放训练。\\n\\n    warmup_eps 个 episode 用 ε-greedy（未训练）采集经验进池子；此后每个 episode：\\n      先以 ε-greedy（随进度退火）访问环境 1 次并把转移入池，再做 updates_per_ep 次回放更新。\\n    \\\"\\\"\\\"\\n    agent = da.DQNAgent(GridDispatchEnv.OBS_DIM, GridDispatchEnv.N_ACTIONS, hidden=hidden, lr=lr,\\n                        gamma=gamma, batch_size=batch_size, buffer_size=200_000, tau=tau, seed=seed)\\n    log = []\\n    t0 = time.time()\\n    for ep in range(total_eps):\\n        eps = eps_start + (eps_end - eps_start) * min(1.0, ep / max(1, total_eps - warmup_eps))\\n        env = GridDispatchEnv(cfg_factory(seed * 1_000_003 + ep))\\n        s = env.reset()\\n        done = False\\n        while not done:\\n            a = agent.act(s, greedy=False, eps=eps)\\n            s2, r, done, _ = env.step(a)\\n            agent.remember(s, a, r, s2, done)\\n            s = s2\\n        if ep >= warmup_eps:\\n            for _ in range(updates_per_ep):\\n                agent.learn()\\n        m = env.day_metrics()\\n        log.append({\\\"episode\\\": ep, \\\"eps\\\": eps, \\\"mean_day_cost\\\": float(m[\\\"cost\\\"].mean()),\\n                    \\\"ess_util\\\": float(m[\\\"ess_util\\\"].mean())})\\n        if verbose and (ep % log_every == 0 or ep == total_eps - 1):\\n            print(f\\\"  offline ep {ep:4d} | eps {eps:.2f} | 日均成本 {log[-1]['mean_day_cost']:8.2f} 元 | \\\"\\n                  f\\\"储能利用率 {log[-1]['ess_util']*100:5.1f}% | {time.time()-t0:5.0f}s\\\", flush=True)\\n    return agent, log\\n\\n\\ndef run_offline(seeds=(0, 1, 2), warmup_eps=20, total_eps=400, train_days=7, eval_days=7,\\n                eval_episodes=10, out_dir=\\\"results\\\", tag=\\\"offline\\\", verbose=True):\\n    os.makedirs(os.path.join(out_dir, \\\"weights\\\"), exist_ok=True)\\n    res = {\\\"baselines\\\": {}, \\\"dqn\\\": []}\\n    f = lambda sd: dataclasses.replace(EnvConfig(), seed=sd, episode_days=eval_days)\\n    for name, pol in da.BASELINES.items():\\n        rows, _ = da.evaluate(pol, f, eval_episodes)\\n        res[\\\"baselines\\\"][name] = da.summarize(rows)\\n    for seed in seeds:\\n        agent, log = train_offline(da.cfg_factory_factory(EnvConfig(), train_days),\\n                                   warmup_eps=warmup_eps, total_eps=total_eps, seed=seed, verbose=verbose)\\n        agent.torch.save(agent.online.state_dict(), os.path.join(out_dir, \\\"weights\\\", f\\\"{tag}_seed{seed}.pt\\\"))\\n        rows, trace = da.evaluate(agent, f, eval_episodes, policy_is_dqn=True, record_trace=True)\\n        s = da.summarize(rows)\\n        s[\\\"seed\\\"] = seed\\n        s[\\\"actions\\\"] = np.bincount(trace[\\\"act\\\"], minlength=4).tolist()\\n        res[\\\"dqn\\\"].append(s)\\n        if verbose:\\n            print(f\\\"  seed={seed} 评估: 日均成本 {s['cost_mean_day']:8.2f} 元 | 储能利用率 {s['ess_util']*100:5.1f}% \\\"\\n                  f\\\"| 动作分布 {s['actions']}\\\", flush=True)\\n    costs = np.array([d[\\\"cost_mean_day\\\"] for d in res[\\\"dqn\\\"]])\\n    summ = {\\\"dqn_mean\\\": float(costs.mean()), \\\"dqn_sd\\\": float(costs.std(ddof=1)) if len(costs) > 1 else 0.0}\\n    for name, b in res[\\\"baselines\\\"].items():\\n        summ[f\\\"reduction_vs_{name}\\\"] = da.reduction({\\\"cost_mean_day\\\": summ[\\\"dqn_mean\\\"]}, b)\\n    res[\\\"summary\\\"] = summ\\n    if verbose:\\n        for name in res[\\\"baselines\\\"]:\\n            print(f\\\"  vs {name:14s}: {summ[f'reduction_vs_{name}']:+6.2f}%\\\")\\n    import json\\n    with open(os.path.join(out_dir, f\\\"summary_{tag}.json\\\"), \\\"w\\\", encoding=\\\"utf-8\\\") as fh:\\n        json.dump(res, fh, ensure_ascii=False, indent=2, default=float)\\n    return res\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    run_offline()\\n\",\"file_path\":\"C:\\\\Users\\\\[USER]\\\\Desktop\\\\西南大学汇报ppt\\\\grid_dispatch_dqn\\\\offline_dqn.py\"}"}
