{"tool":"write","arguments":"{\"content\":\"\\\"\\\"\\\"Run the metis Bayesian search over the FedDRL training configuration.\\\"\\\"\\\"\\nimport json\\nimport sys\\nimport time\\n\\nsys.path.insert(0, r\\\"C:\\\\Users\\\\[USER]\\\\Documents\\\\finetune-lab\\\\.venv\\\\Lib\\\\site-packages\\\")\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport torch\\n\\ntorch.set_num_threads(4)\\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\\n\\nfrom fedpt.data import build_dataset                                     # noqa: E402\\nfrom feddrl_repro.ddpg import DDPGConfig                                 # noqa: E402\\nfrom feddrl_repro.federated import FedConfig, run_feddrl, predict_all, metrics  # noqa: E402\\nfrom feddrl_repro.metis import MetisTuner                                # noqa: E402\\n\\nOUT = Path(\\\"feddrl_repro/results\\\")\\nOUT.mkdir(parents=True, exist_ok=True)\\n\\nds = build_dataset(verbose=False)\\nC = ds.clients\\nH, WL, NC = C[0].Y_train.shape[1], C[0].X_train.shape[1], C[0].X_train.shape[2]\\ndev = \\\"cuda\\\"\\n\\n# validation objective: mean NRMSE over the validation split of all clients,\\n# after a short federated run (W=3, K=1, E=1) -- cheap but discriminative\\nW_TUNE = 3\\n\\n\\ndef objective(p: dict):\\n    t0 = time.time()\\n    cfg = DDPGConfig(actor_lr=p[\\\"actor_lr\\\"], critic_lr=p[\\\"critic_lr\\\"], gamma=p[\\\"gamma\\\"],\\n                     actor_hidden=p[\\\"actor_hidden\\\"], critic_hidden=p[\\\"critic_hidden\\\"],\\n                     batch_size=128, noise_std=0.05, warmup_steps=256,\\n                     updates_per_step=4, episode_chunk=256, replay_capacity=60000)\\n    fed = FedConfig(n_global_epochs=W_TUNE, local_episodes=1, K=1, E=1.0,\\n                    replay_capacity=60000)\\n    try:\\n        _, models, hist = run_feddrl(C, cfg, fed, H, NC, WL, seed=0, device=dev)\\n        vals = []\\n        for c, m in zip(C, models):\\n            pred = predict_all(m, c.X_val, dev, H).numpy()\\n            vals.append(metrics(c.Y_val.numpy(), pred)[\\\"NRMSE\\\"])\\n        return float(np.mean(vals)), {\\\"elapsed_s\\\": round(time.time() - t0, 1),\\n                                      \\\"per_client\\\": [round(v, 3) for v in vals]}\\n    except Exception as exc:                      # a failed trial is a bad trial\\n        return 1e3, {\\\"error\\\": f\\\"{type(exc).__name__}: {exc}\\\"}\\n\\n\\ntuner = MetisTuner(objective, n_init=6, seed=0)\\nresult = tuner.run(n_trials=14)\\nwith open(OUT / \\\"metis_search.json\\\", \\\"w\\\", encoding=\\\"utf-8\\\") as fh:\\n    json.dump({\\\"paper_note\\\": \\\"metis AutoML stage of Sec. III-B / Tab. I\\\",\\n               \\\"objective\\\": f\\\"mean validation NRMSE over 6 zones, W={W_TUNE}, K=1, E=1\\\",\\n               **result}, fh, indent=2)\\nprint(\\\"\\\\nBEST:\\\", json.dumps(result[\\\"trials\\\"][0], indent=2))\\n\",\"file_path\":\"C:\\\\Users\\\\[USER]\\\\Documents\\\\deepseek-harness\\\\default-workspace\\\\feddrl_repro\\\\run_metis.py\"}"}
